'use strict';
let bankView=null;
function taxPanel(){const t=state.tax||M.defaultTax(),c=M.estimateTax(t),paid=state.payments.find(p=>p.id==='tax')?.paid;return `<section class="card tax-panel"><div class="card-heading"><div><h2>Налоговый план</h2><p>ИП · УСН «Доходы» 6% · 9 месяцев 2026</p></div><span class="tag ${paid?'green':'red'}">${paid?'Оплата учтена':'До 28 октября'}</span></div><div class="tax-summary"><div><span>${paid?'Учтённый аванс':'Аванс к уплате'}</span><strong>${money(c.payable)}</strong></div><div class="tax-formula"><span>${money(c.gross)} налог</span><span>− ${money(c.deduction)} взносы</span><span>− ${money(t.priorAdvances)} предыдущие авансы</span></div>${paid?'<span class="tag green">Отражено в остатке</span>':'<button class="btn secondary" data-business="tax">Уточнить расчёт</button>'}</div><p class="small-caption">Ставка 6%, без НДС и региональных льгот. В сценарии доходы за 2025 год не превышали 20 млн ₽. При работниках вычет взносов ограничен 50% налога. <a class="text-btn" href="https://www.nalog.gov.ru/rn91/ifns/ifns_simph/info/16608587/" target="_blank" rel="noopener noreferrer">Правила и сроки ФНС ↗</a></p></section>`}
function taxModal(){const t=state.tax||M.defaultTax();modal('Уточнить аванс УСН',`<p>Расчёт за 9 месяцев нарастающим итогом. Укажите доходы налогового учёта, взносы, принимаемые к вычету, и ранее исчисленные авансы.</p><form id="tax-form"><div class="field"><label for="tax-income">Доход с января по сентябрь, ₽</label><input id="tax-income" name="income" type="number" min="0" max="20000000" step="1" value="${t.income}" required></div><div class="field-row"><div class="field"><label for="tax-contributions">Взносы к вычету, ₽</label><input id="tax-contributions" name="contributions" type="number" min="0" max="10000000" step="1" value="${t.contributions}" required></div><div class="field"><label for="tax-prior">Предыдущие авансы, ₽</label><input id="tax-prior" name="priorAdvances" type="number" min="0" max="10000000" step="1" value="${t.priorAdvances}" required></div></div><label class="checkbox-field"><input type="checkbox" name="employees" ${t.employees?'checked':''}>Есть работники</label><div class="tax-live" id="tax-live">К уплате: ${money(M.estimateTax(t).payable)}</div><p class="inline-note">Сценарий без НДС, по стандартной ставке. Региональные льготы, торговый сбор и специальные основания не учитываются. Сверьте налоговую базу и вычеты с учётом перед оплатой.</p><div class="field-error" id="tax-error" role="alert"></div><button class="btn primary full" type="submit">Сохранить и обновить прогноз</button></form>`)}
function taxFormValue(form){const d=new FormData(form);return {income:Number(d.get('income')),contributions:Number(d.get('contributions')),priorAdvances:Number(d.get('priorAdvances')),employees:d.has('employees')}}
function bankAPIModal(){modal('Подключить счёт Альфа-Банка',`<p>Ритм может получить выписку через официальный Alfa API. Нужен доступ владельца счёта к сервису transactions. Подключение выполняется только для чтения.</p><form id="bank-form" autocomplete="off"><div class="field-row"><div class="field"><label for="bank-environment">Среда</label><select id="bank-environment" name="environment"><option value="production">Реальный счёт</option><option value="sandbox">Песочница банка</option></select></div><div class="field"><label for="bank-auth">Авторизация</label><select id="bank-auth" name="authType"><option value="apikey">API Key · H2H</option><option value="bearer">Bearer access token</option></select></div></div><div class="field"><label for="bank-account">Номер счёта · 20 цифр</label><input id="bank-account" name="account" inputmode="numeric" pattern="[0-9]{20}" maxlength="20" placeholder="40702…" required></div><div class="field"><label for="bank-token">Ключ или токен Alfa API</label><input id="bank-token" name="token" type="password" autocomplete="new-password" minlength="8" maxlength="8192" required></div><div class="field"><label for="bank-date">Дата выписки</label><input id="bank-date" name="date" type="date" value="${M.DATE}" min="2021-01-01" required></div><label class="checkbox-field"><input type="checkbox" name="consent" required>Разрешаю запрос выписки указанного счёта</label><p class="inline-note">Пароль банка и коды СМС не нужны. Выписка не отправляется ИИ. Сейчас запрашивается первая страница операций за дату. <a class="text-btn" href="https://developers.alfabank.ru/" target="_blank" rel="noopener noreferrer">Получить доступ к Alfa API ↗</a></p><div class="field-error" id="bank-error" role="alert"></div><button class="btn primary full" type="submit">Подключить и получить выписку</button></form>`)}
function bankPanel(){if(!bankView?.connected)return '';const amount=n=>new Intl.NumberFormat('ru-RU',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n/100)+' ₽';return `<section class="card tax-panel"><div class="card-heading"><div><h2>Выписка Альфа-Банка</h2><p>Счёт ${esc(bankView.accountMasked)} · ${date(bankView.date)} · ${bankView.environment==='production'?'реальный счёт':'песочница банка'}</p></div><button class="text-btn" data-business="bank-disconnect">Отключить</button></div><div class="table-scroll"><table class="data-table"><thead><tr><th>Операция</th><th>Направление банка</th><th class="amount">Сумма в рублях</th></tr></thead><tbody>${bankView.rows.length?bankView.rows.map((r,i)=>`<tr><td>Операция ${i+1}</td><td>${esc(r.direction)}</td><td class="amount">${amount(r.amountKopecks)}</td></tr>`).join(''):'<tr><td colspan="3">Рублёвых операций за выбранную дату нет.</td></tr>'}</tbody></table></div><p class="small-caption">Первая страница выписки${bankView.hasNext?' · у банка есть следующие страницы':''}. Банковская выписка отображается отдельно и не изменяет текущий сценарий кофейни. Отправка платежей не выполняется.</p></section>`}
async function initBusiness(){if(!online)return;try{bankView=await api('/api/bank/status');if(bankView.connected){$('#connect-bank').dataset.connected='true';$('#connect-bank').title='Выписка Alfa API получена';$('#bank-label').textContent='Счёт '+bankView.accountMasked;render()}}catch{}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-business]');if(!b)return;if(b.dataset.business==='tax')taxModal();if(b.dataset.business==='bank')bankAPIModal();if(b.dataset.business==='bank-disconnect'){b.disabled=true;try{await post('/api/bank/disconnect');bankView=null;$('#connect-bank').dataset.connected='false';$('#connect-bank').title='Банк не подключён';$('#bank-label').textContent='Подключить счёт';render();notify('Счёт отключён.')}catch(err){notify(err.message);b.disabled=false}}if(b.dataset.business==='delete-expense'){modal('Удалить расход',`<p>Операция будет удалена из учёта. Баланс и прогноз пересчитаются.</p><div class="modal-actions"><button class="btn soft" data-action="close">Отмена</button><button class="btn primary" data-business="confirm-delete" data-id="${esc(b.dataset.id)}">Удалить расход</button></div>`)}if(b.dataset.business==='confirm-delete'){b.disabled=true;try{if(online)await api('/api/expenses/'+encodeURIComponent(b.dataset.id),{method:'DELETE'});else{state.expenses=state.expenses.filter(v=>v.id!==b.dataset.id);saveLocal()}await sync();closeModal();render();notify('Расход удалён. Прогноз обновлён.')}catch(err){notify(err.message);b.disabled=false}}});
document.addEventListener('input',e=>{if(e.target.closest('#tax-form')){const t=taxFormValue($('#tax-form'));$('#tax-live').textContent='К уплате: '+money(M.estimateTax(t).payable)}});
document.addEventListener('submit',async e=>{if(e.target.id==='tax-form'){e.preventDefault();const c=taxFormValue(e.target),b=e.target.querySelector('[type=submit]');b.disabled=true;try{if(online)await post('/api/tax',c);else{const p=state.payments.find(v=>v.id==='tax');if(p.paid)throw Error('Аванс уже учтён оплаченным');state.tax=c;p.amount=M.estimateTax(c).payable;saveLocal()}await sync();closeModal();render();notify('Налоговый расчёт сохранён. Прогноз обновлён.')}catch(err){$('#tax-error').textContent=err.message;b.disabled=false}}if(e.target.id==='bank-form'){e.preventDefault();if(!online){$('#bank-error').textContent='Для подключения счёта запустите полную версию с Go-сервером.';return}const values=Object.fromEntries(new FormData(e.target));values.consent=true;const b=e.target.querySelector('[type=submit]');b.disabled=true;b.textContent='Запрашиваем выписку…';try{bankView=await post('/api/bank/connect',values);$('#bank-token').value='';$('#connect-bank').dataset.connected='true';$('#connect-bank').title='Выписка Alfa API получена';$('#bank-label').textContent='Счёт '+bankView.accountMasked;closeModal();navigate('payments');render();notify('Alfa API ответил. Выписка получена.')}catch(err){$('#bank-error').textContent=err.message;b.disabled=false;b.textContent='Подключить и получить выписку'}finally{values.token=''}}});
